# -*- coding: utf-8 -*-
"""MANAPRINT - Generateur VALIDER (A4 portrait, 16 cartons/feuille).

REGLE ABSOLUE : le decor plus bas EST la planche de Maeva, relevee au trait
   sur sa maquette (le cadre, le bandeau << N deg ___ >>, le titre << VALIDER >>
   avec sa case cochee, les SIX cercles doubles labellises N . G . O, le
   presse-papier, << JOUEZ . COCHEZ . VALIDEZ ! >> et les etincelles). RIEN
   n'a ete redessine : on ECRIT seulement les numeros sous chaque lettre.

LA REGLE DU JEU : SIX numeros, selon les lettres des cercles -
   N 31-45 (DEUX cercles, en haut) . G 46-60 (DEUX cercles, au milieu) .
   O 61-75 (DEUX cercles, en bas). Le crieur sort 31-75.

L'ARC-EN-CIEL EST CARTON PAR CARTON : la planche n'est gravee qu'une fois,
   puis reposee seize fois dans la couleur de SON carton. En N&B au gris
   #555555. Les chiffres gardent le gris de la maison.
"""
import io
import random
from reportlab.pdfgen import canvas
from reportlab.lib.pagesizes import A4
from reportlab.lib import colors
from reportlab.lib.units import mm
from reportlab.pdfbase import pdfmetrics
from reportlab.pdfbase.ttfonts import TTFont

try:
    from generators import securite as _sec
except Exception:
    try:
        import securite as _sec
    except Exception:
        _sec = None

